UPDATE `skillline` SET `name_kokr` = '대장기술', `name_frfr` = 'Forge', `name_dede` = 'Schmiedekunst', `name_zhcn` = '锻造', `name_eses` = 'Herrería', `name_esmx` = 'Herrería', `name_ruru` = 'Кузнечное дело', `desc_kokr` = '대장기술 숙련도가 올라갈수록 고레벨의 대장기술 도면을 배울 수 있습니다. 도면은 전문 대장장이나 퀘스트를 통해 배우거나 몬스터에게서 얻을 수 있습니다.', `desc_frfr` = 'Un plus haut score dans la compétence forge vous permet d’apprendre des plans plus difficiles. Les plans pour forgerons se trouvent dans le monde entier auprès de maîtres aussi bien qu’en récompense de quêtes ou qu’en butin de monstres.', `desc_dede` = 'Eine hohe Schmiedefertigkeit e', `desc_zhcn` = '高级的锻造技能使你可以学习高级的锻造设计图。你可以在训练师那', `desc_eses` = 'Con un nivel alto de habilidad en herrería, podrás aprender mejores diseños de herrería. Visita a los instructores dispersos por el mundo, completa misiones y derrota a los monstruos para conseguirlos.', `desc_esmx` = 'Con un nivel alto de habilidad en herrería, podrás aprender mejores diseños de herrería. Visita a los instructores dispersos por el mundo, completa misiones y derrota a los monstruos para conseguirlos.', `desc_ruru` = 'Чем лучше развит этот навык, тем более сложные кузнечные чертежи вы можете использовать. Чертежи можно найти у учителей, а также получить в качестве добычи или награды.', `verb_kokr` = '개조', `verb_frfr` = 'Modifier', `verb_dede` = 'Umarbeiten', `verb_zhcn` = '修改', `verb_eses` = 'Transformar', `verb_esmx` = 'Transformar', `verb_ruru` = 'Выковать' WHERE `id` = 164;
