UPDATE `skillline` SET `name_kokr` = '낚시', `name_frfr` = 'Pêche', `name_dede` = 'Angeln', `name_zhcn` = '钓鱼', `name_eses` = 'Pesca', `name_esmx` = 'Pesca', `name_ruru` = 'Рыбная ловля', `desc_kokr` = '낚시 숙련도가 올라갈수록 물고기를 낚을 확률이 증가합니다. 만약 해당 지역에서 물고기를 낚을 수 없다면 좀 더 낮은 레벨의 장소로 이동하거나 미끼를 사용해 보십시오.', `desc_frfr` = 'Un plus haut score dans la compétence pêche augmente vos chances d\'attraper des poissons dans le monde. Si vous n\'arrivez pas à pêcher dans une zone spécifique, allez dans des zones de plus bas niveau ou utilisez des appâts.', `desc_dede` = 'Eine hohe Angelfertigkeit stei', `desc_zhcn` = '高级的钓鱼技能使你可以钓到高级的鱼。如果你在某个区域钓不到鱼', `desc_eses` = 'Con un nivel alto de habilidad en pesca aumentará la probabilidad de que pesques algo en las aguas del mundo. Si te cuesta mucho pescar, ve a pescar a otra área de nivel inferior o compra un cebo.', `desc_esmx` = 'Con un nivel alto de habilidad en pesca aumentará la probabilidad de que pesques algo en las aguas del mundo. Si te cuesta mucho pescar, ve a pescar a otra área de nivel inferior o compra un cebo.', `desc_ruru` = 'Чем лучше развит этот навык, тем больше вероятность поимки рыбы в любом из водоемов. Если вам не везет на рыбалке, перейдите в область более низкого уровня или купите приманку.' WHERE `id` = 356;
