UPDATE `skillline` SET `name_kokr` = '무두질', `name_frfr` = 'Dépeçage', `name_dede` = 'Kürschnerei', `name_zhcn` = '剥皮', `name_eses` = 'Desollar', `name_esmx` = 'Desollar', `name_ruru` = 'Снятие шкур', `desc_kokr` = '무두질 숙련도가 올라갈수록 고레벨의 몬스터의 가죽을 채집할 수 있습니다. 숙련도가 100 이상이 되면 숙련도를 5로 나눈 숫자가 가죽 채집이 가능한 몬스터의 최고 레벨입니다.', `desc_frfr` = 'Une compétence en dépeçage plus élevée vous permet de récolter les peaux de monstres plus puissants. Une fois que votre compétence dépasse 100, vous pouvez la diviser par 5 pour connaître le niveau maximum des monstres que vous pouvez dépecer.', `desc_dede` = 'Eine hohe Kürschnerfertigkeit ', `desc_zhcn` = '高级的剥皮技能使你可以从高级怪物身上剥取毛皮。如果你的剥皮技', `desc_eses` = 'Con un nivel alto de habilidad en desollar podrás despellejar monstruos de nivel superior. Cuando tu habilidad sea superior a 100, podrás dividirla entre 5 para determinar hasta qué nivel puedes despellejar.', `desc_esmx` = 'Con un nivel alto de habilidad en desollar podrás despellejar monstruos de nivel superior. Cuando tu habilidad sea superior a 100, podrás dividirla entre 5 para determinar hasta qué nivel puedes despellejar.', `desc_ruru` = 'Чем лучше развит этот навык, тем выше уровень монстров, с которых вы можете снимать шкуры. Если значение навыка больше 100, разделите его на 5 – и вы узнаете максимальный уровень монстра, снять шкуру которого вам по силам.' WHERE `id` = 393;
